#include <regex>
#include <string>
#include <sstream>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::regex pattern{"(a+)"};
    pattern.assign("(a+)");
    assert(pattern.flags() == std::regex::ECMAScript);
    auto locale = pattern.getloc();
    pattern.imbue(locale);
    pattern.assign("(a+)");
    std::regex other;
    other = pattern;
    other.swap(pattern);
    std::swap(other, pattern);
    std::string input = "aa a";
    std::smatch result;
    assert(std::regex_search(input, result, other));
    assert(!result.empty() && result.length() == 2 && result.begin() != result.end() &&
        result.max_size() >= result.size());
    auto allocator = result.get_allocator();
    (void)allocator;
    std::smatch copy;
    copy = result;
    assert(copy == result);
    copy.swap(result);
    std::swap(copy, result);
    assert(result[1].compare("aa") == 0 && result[1] == std::string("aa"));
    std::sregex_iterator position{input.begin(), input.end(), other}, end;
    auto next = position;
    ++next;
    assert(next != position);
    position = next;
    assert(position == next);
    std::sregex_token_iterator token{input.begin(), input.end(), other, 1}, tokenEnd;
    assert(token != tokenEnd && token->str() == "aa");
    auto tokenCopy = token;
    ++tokenCopy;
    token = tokenCopy;
    std::regex_traits<char> traits;
    traits.imbue(std::locale::classic());
    (void)traits.getloc();
    assert(traits.translate('A') == 'A' && traits.translate_nocase('A') == 'a');
    assert(!traits.transform(input.begin(), input.end()).empty());
    std::regex_error error{std::regex_constants::error_brack}, assigned = error;
    assigned = error;
    assert(error.code() == assigned.code());
    std::regex_constants::match_flag_type flags = std::regex_constants::match_default;
    (void)flags;
}
